  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral rappelle que si le jugement est peu clair ou incomplet, il appartient au tribunal de première instance de clarifier la situation (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Selon l'art. 73 al. 2 CP, l'utilisation de l'équivalent de la créance compensatrice en faveur du lésé n'est possible que si celui-ci cède sa créance au profit de l'État (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le tribunal de l'exécution ne doit ni examiner le fond de la créance ni se prononcer sur la justesse matérielle du jugement (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La formulation du dispositif du jugement pénal, utilisant le passé composé («abgetreten hat») et la mention de l'abtretement, démontre que la cession a déjà eu lieu (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Une paiement du débiteur au cédant après la cession ne libère pas le débiteur envers le cessionnaire, sauf accord exprès du cessionnaire (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le tribunal de la mainlevée ne peut pas examiner le fond de la créance ni la justesse matérielle du jugement (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le dispositif du jugement pénal indique que la créance en dommages-intérêts de la partie lésée a été cédée à l'intimé à hauteur de 70'000 francs.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la créance en dommages-intérêts cédée à l'intimé à hauteur de 70'000 francs n'est pas éteinte.",
      "b_propositions": ["P8"]
    }
  ]
}
